//! 🛂️ Explicit neutral test caller admission keeps one original observer and recipient throughout real runtime calls.
use semio_framework_value::{NativeEncodeControl,native_encoding::{NativeEncodeRetirementRecipient},OriginalRetirementFailure,RetainedCloneGrant,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,ValueError};
use semio_os_vcs::io::binary::entity_identity::control::{EntityIdentityAuthority,Observer};
fn policy()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🛂️receiving/🔣️.json")).unwrap()}
pub fn original<'a>(observer:&'a mut Observer<'a>,recipient:&'a mut NativeEncodeRetirementRecipient)->EntityIdentityAuthority<'a>{let law=policy();let receipt=NativeEncodeControl::new(law["maximumNativeBytes"].as_u64().unwrap()as usize,observer).pause().unwrap();let receipt=receipt.with_retirement_recipient(recipient).unwrap_or_else(|_|panic!("original test recipient is not empty"));EntityIdentityAuthority::resume_retirement(receipt,observer)}
/// ♻️ Runs one reply-shaped encoder recipient close inside one host-funded retirement turn; an unadmitted quote or a pending poll keeps the owner and reports no progress.
pub fn close_recipient_step(control:&mut NativeEncodeControl<'_>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
 let body=grant.maximum_copy_bytes;
 let ran=semio_framework_job::OriginalRetirementPump::new().turn(1<<16,u64::MAX,||Some(0),grant)?.with_effect(|effect|{let mut slot=None;let recorded=semio_framework_value::retirement::__control::OriginalEffectReply::borrow(&mut slot).and_then(|reply|control.close_retirement_recipient_into(body,effect,reply).map(|_|()));let result=match recorded{Ok(())=>slot.take().expect("encoder close records its reply"),Err(error)=>Err(OriginalRetirementFailure::from(error))};RetainedWorkPoll::Complete(RetainedWorkOutcome{result,work:effect.performed_work()})})?;
 match ran{Some((RetainedWorkPoll::Complete(outcome),_))=>outcome.result.map_err(OriginalRetirementFailure::into_value_error),_=>Ok(RetainedCloneStep::Progress(Default::default()))}
}
pub fn close(identity:&mut EntityIdentityAuthority<'_>){let law=policy();let grant=&law["grant"];let grant=RetainedCloneGrant{maximum_items:grant["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:grant["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:grant["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:grant["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:grant["maximumDepth"].as_u64().unwrap()as usize};let maximum=law["maximumCloseTurns"].as_u64().unwrap();identity.encode(|control|{let mut turns=0;while control.has_retirement_owner(){let step=close_recipient_step(control,grant)?;assert!(step.progress().fits(grant));turns+=1;assert!(turns<=maximum,"original test retirement remains pending");}Ok::<_,semio_framework_value::ValueError>(())}).unwrap();}

/// 🎟️ The one neutral original retained turn every host test hands the runtime it drives.
pub fn original_retained_turn()->semio_framework_actor::RetainedTurnInput{let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../🔨️modules/🎭️actor/🎟️retained-turn/📃️policy/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();serde_json::from_value(law["input"].clone()).unwrap()}
/// 🪙️ The whole held source authority of [`original_retained_turn`] as the loan one activation grants its actor.
pub fn original_retained_loan()->semio_framework_actor::OriginalActorTurnLoan{let input=original_retained_turn();semio_framework_actor::OriginalActorTurnLoan{retained_policy:input.grant,work_fuel:input.work.fuel,deadline_us:input.work.absolute_deadline_us}}
pub fn idle_receipt()->semio_framework_actor::RetainedTurnReceipt{original_retained_turn().return_original(semio_framework_value::RetainedCloneProgress::default(),0).expect("idle turn spends nothing")}
